import struct

def crc32c(data):
    poly = 0x82F63B78
    crc = 0xFFFFFFFF
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = (crc >> 1) ^ (poly if crc & 1 else 0)
    return crc ^ 0xFFFFFFFF

data = open('samples/basic.kdmp','rb').read()
target = struct.unpack('<I', bytes.fromhex("d1dd35a1"))[0]
print("target crc32c = %08x" % target)
# search all windows length 1..64
for L in range(1, 65):
    for o in range(len(data)-L+1):
        if crc32c(data[o:o+L]) == target:
            print("FOUND len=%d offset=%d (0x%x): %s" % (L, o, o, data[o:o+L].hex()))
EOF

