python3 - <<'EOF'
import struct
M = (1<<64)-1

def crc64_ref(data, poly, init=0, xorout=0):
    crc = init
    for b in data:
        crc ^= b
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ poly
            else:
                crc >>= 1
    return (crc ^ xorout) & M

def crc64_norm(data, poly, init=0, xorout=0):
    crc = init
    for b in data:
        crc ^= b << 56
        for _ in range(8):
            if crc & (1<<63):
                crc = ((crc << 1) ^ poly) & M
            else:
                crc = (crc << 1) & M
    return (crc ^ xorout) & M

ECMA_N = 0x42F0E1EBA9EA3693   # normal
ECMA_R = 0xC96C5795D7870F42   # reflected
ISO_N  = 0x000000000000001B   # normal
ISO_R  = 0xD800000000000000   # reflected

variants = {
 "ECMA_ref": lambda d: crc64_ref(d, ECMA_R),
 "ISO_ref":  lambda d: crc64_ref(d, ISO_R),
 "ECMA_norm": lambda d: crc64_norm(d, ECMA_N),
 "ISO_norm": lambda d: crc64_norm(d, ISO_N),
 "ECMA_norm_xz": lambda d: crc64_norm(d, ECMA_N, M, M),
 "ISO_norm_we": lambda d: crc64_norm(d, ISO_N, M, M),
}

files = {
 'basic': ('samples/basic.kdmp', 116, 141, 144),
 'empty': ('samples/empty_sections.kdmp', 96, 96, 96),
 'align': ('samples/alignment_gaps.kdmp', 127, 127, 128),
}

for name,(f,ent_end,meta_end,data_start) in files.items():
    d = open(f,'rb').read()
    target_le = struct.unpack('<Q', d[8:16])[0]
    target_be = struct.unpack('>Q', d[8:16])[0]
    print("=== %s target LE=%016x BE=%016x" % (name, target_le, target_be))
    regions = {
      "whole_zeroed8": d[:8] + b"\x00"*8 + d[16:],
      "body16": d[16:],
      "entries": d[16:ent_end],
      "entries+meta": d[16:meta_end],
      "entries+meta+pad": d[16:data_start],
      "data": d[data_start:],
    }
    for rn, r in regions.items():
        for vn, fn in variants.items():
            v = fn(r)
            if v == target_le:
                print("  MATCH LE: %s over %s" % (vn, rn))
            if v == target_be:
                print("  MATCH BE: %s over %s" % (vn, rn))
    print()
EOF

